<?php require_once 'auth.php'; if (current_user()) redirect('dashboard.php'); $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['name']??''); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; if(!$name||!$email||strlen($password)<6) $error='Add your name, a valid email, and a password with 6+ characters.'; elseif(one('SELECT id FROM users WHERE email=?','s',[$email])) $error='An account already exists for that email.'; else { query('INSERT INTO users (name,email,password_hash,role) VALUES (?,?,?,\'student\')','sss',[$name,$email,password_hash($password,PASSWORD_DEFAULT)]); $id=db()->insert_id; query('INSERT INTO students (user_id,university,course,semester) VALUES (?,?,?,?)','isss',[$id,trim($_POST['university']??'Northbridge University'),trim($_POST['course']??'B.Tech Computer Science'),trim($_POST['semester']??'Semester 1')]); $_SESSION['user_id']=$id; redirect('dashboard.php'); } } $pageTitle='Create profile'; include 'includes/header.php'; ?><div class="auth-page"><div class="auth-panel"><a class="brand" href="index.php"><span class="brand-mark">S</span><span>skill<span>rank</span></span></a><div class="auth-heading"><div class="eyebrow">Your growth starts here</div><h1>Make progress visible.</h1><p>Build a profile that gets smarter with every attempt.</p></div><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post" class="form-stack"><label>Full name<input name="name" required placeholder="Aarav Kapoor"></label><label>Email address<input type="email" name="email" required placeholder="you@university.edu"></label><div class="form-grid"><label>University<input name="university" value="Northbridge University"></label><label>Course<input name="course" value="B.Tech Computer Science"></label></div><label>Semester<input name="semester" value="Semester 1"></label><label>Password<input type="password" name="password" required minlength="6" placeholder="At least 6 characters"></label><button class="button button-primary full" type="submit">Create my profile <span>↗</span></button></form><p class="form-note">Already have an account? <a href="login.php">Sign in</a></p></div><div class="auth-art auth-art-alt"><div class="auth-stat"><strong>+12.4%</strong><span>average skill growth<br>after 30 days</span></div></div></div><?php include 'includes/footer.php'; ?>